&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;KEY&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; RESPONSIBILITIES&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Lead platform security efforts by assessing risks, hardening &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;platforms&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;, and ensuring secure access for cloud and on-premises systems.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;Own &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;the security standard for Firmus Managed Kubernetes Service &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;for high-performance computing &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;product offering to customers&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; with NVIDIA H200 and GB300&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
